+    visual_quality_points_stream
+        << frame_index << ',' << img_time_s << ',' << img_rel_s << ',' << i
+        << ',' << stage << ',' << u << ',' << v
+        << ',' << pt->pos_[0] << ',' << pt->pos_[1] << ',' << pt->pos_[2]
+        << ',' << point_camera[2] << ',' << point_camera.norm() << ',' << view_cos
